function IntegrationsIndexInner() {
  const [page, setPage] = useState(1);
  const [sort, setSort] = useState<string | undefined>(undefined);
  void setSort;

  const [filters, setFilters] = useState<{ kind?: string }>({});
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const setFilter = (key: keyof typeof filters, value: string) => {
    setFilters(current => ({ ...current, [key]: value }));
    setPage(1);
  };
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = {
    page,
    page_size: PAGE_SIZE,
    kind: filters.kind || undefined
  } as Inputs["integrations"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.integrations.list(input) });
  const router = useRouter();
  const queryClient = useQueryClient();

  return (
    <div className="flex h-full min-h-0 flex-col">
      <PaneHeader title="Integrations" count={list.data?.page.total}>
          {canCreate(user) ? (
            <Link href="/integrations/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New integration">
              <Plus />
            </Link>
          ) : null}
      </PaneHeader>


      <div className="flex flex-wrap items-center gap-2 border-b border-border px-4 py-2">

          <select aria-label="Kind" className={selectClass + " w-auto"} value={filters.kind ?? ""} onChange={e => setFilter("kind", e.target.value)}>
            <option value="">Kind: any</option>
            <option value="webhook">webhook</option>
            <option value="slack">slack</option>
            <option value="email">email</option>
          </select>
      </div>
      <div className="min-h-0 flex-1 overflow-auto px-4">
        {list.isPending ? (
          <ListSkeleton />
        ) : list.error ? (
          <ErrorNote error={list.error} className="m-4" />
        ) : list.data.data.length === 0 ? (
          <EmptyPane>No integrations found.</EmptyPane>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>Name</TableHead>
                <TableHead>Kind</TableHead>
                <TableHead>Created At</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {list.data.data.map((row: Row) => (
                <TableRow key={text(row.id)} className="cursor-pointer" onClick={() => router.push(`/integrations/${text(row.id)}`)}>
                  <TableCell>{text(row.name)}</TableCell>
                  <TableCell>{text(row.kind)}</TableCell>
                  <TableCell>{formatDateTime(row.created_at)}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
      {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
    </div>
  );
}

function IntegrationsNewInner() {
  const router = useRouter();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.integrations.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push(`/integrations/${text(row.id)}`);
    }
  });
  return (
    <Pane title="New integration" actions={<Link href="/integrations" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <IntegrationsForm
        fields={INTEGRATIONS_CREATE}
        initial={EMPTY_INTEGRATIONS}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toIntegrationsCreateInput(values))}
      />
    </Pane>
  );
}

function IntegrationsDetailInner() {
  const { id: rawId } = useParams<{ id: string }>();
  const id = idOf(rawId);
  const router = useRouter();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.integrations.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["integrations"]["update"]) => client.integrations.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["integrations"]["delete"]) => client.integrations.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await router.push("/integrations");
    }
  });
  const signAction = useMutation({
    mutationFn: (input: Inputs["integrations"]["sign"]) => client.integrations.sign(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.name) || "Integration " + text(row.id)}
      actions={
        <>
          <Link href="/integrations" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canSign(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setOpenAction(open => (open === "sign" ? null : "sign"))}>
              Sign
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this integration?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >
      {openAction === "sign" ? (
        <div className="mb-6 rounded-md border border-border p-4">
          <IntegrationsSignForm fields={INTEGRATIONSSIGN_CREATE} initial={EMPTY_INTEGRATIONSSIGN} submitLabel="Sign" pending={signAction.isPending} error={signAction.error} onCancel={() => setOpenAction(null)} onSubmit={values => signAction.mutate({ id, ...toIntegrationsSignCreateInput(values) })} />
        </div>
      ) : null}

      {editing ? (
        <IntegrationsForm
          fields={INTEGRATIONS_UPDATE}
          initial={integrationsFromRow(row)}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toIntegrationsUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Name">{text(row.name) || "—"}</FieldRow>
        <FieldRow label="Kind">{row.kind == null ? "—" : <Badge variant="secondary">{text(row.kind)}</Badge>}</FieldRow>
        <FieldRow label="Config">
          <pre className="overflow-x-auto rounded-md bg-muted p-3 text-xs">{formatJson(row.config) || "—"}</pre>
        </FieldRow>
        {"secret" in row ? (
          <FieldRow label="Secret">{text(row.secret) || "—"}</FieldRow>
        ) : null}
        {"token" in row ? (
          <FieldRow label="Token">{text(row.token) || "—"}</FieldRow>
        ) : null}
        <FieldRow label="Created At">{formatDateTime(row.created_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const IntegrationsLayout = guarded(IntegrationsLayoutInner);
export const IntegrationsIndex = guarded(IntegrationsIndexInner);
export const IntegrationsNew = guarded(IntegrationsNewInner);
export const IntegrationsDetail = guarded(IntegrationsDetailInner);
